from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
V=np.var(y)
def res(q, form):
    a,k,c,j=q
    if form==0: g=P**k/(1+c*P)
    if form==1: g=P**k*np.exp(-c*P)
    if form==2: g=P**k/(1+c*P**2)
    if form==3: g=P**k*(1-np.exp(-c*P))
    X=np.column_stack([P**2, np.tanh(a*t), np.tanh(a*t)*P**3, g*t**j])
    co,*_=np.linalg.lstsq(X,y,rcond=None)
    return X@co-y
